import com.comsol.model.*;import com.comsol.model.util.*;
public class EvalCoupledModalElectric{public static void main(String[]a)throws Exception{ModelUtil.initStandalone(true);Model m=ModelUtil.load("m","D:\\comsol_ao_run\\convergence\\Wap_6um_coupled_eigen_refined4.mph");try{String[]ds=m.result().dataset().tags();String d=ds[ds.length-1];m.result().numerical().create("evalCme","EvalGlobal");m.result().numerical("evalCme").set("data",d);m.result().numerical("evalCme").set("looplevelinput",new String[]{"all"});m.result().numerical("evalCme").set("expr",new String[]{"freq","intLN(abs(V))","intLN(abs(u))","intLN(abs(v))","intLN(abs(w))","intLN(abs(solid.eXX))","intLN(abs(solid.eYY))","intLN(abs(solid.eZZ))"});double[][]r=m.result().numerical("evalCme").getReal();for(int j=0;j<r[0].length;j++)System.out.printf(java.util.Locale.US,"MODE %d f=%.9f V=%.6e u=%.6e v=%.6e w=%.6e exx=%.6e eyy=%.6e ezz=%.6e%n",j+1,r[0][j]/1e9,r[1][j],r[2][j],r[3][j],r[4][j],r[5][j],r[6][j],r[7][j]);}catch(Throwable t){t.printStackTrace(System.out);}finally{ModelUtil.disconnect();}}}
